const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definition
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const cambodia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));
  const geometry = cambodia.geometry();

  if (geometry.area().getInfo() === 0) {
    console.log("Error: Could not retrieve Cambodia geometry.");
    console.log("D");
    return;
  }

  // Define the fire collection
  const fireCollection = ee.ImageCollection('MODIS/051/MOD14A1'); // MODIS Terra Thermal Anomalies & Fire

  // Function to get total high-confidence fire pixels for a given date range
  const getFirePixels = async (startMonth, endMonth, startDay, endDay, label) => {
    let allFireImages = ee.ImageCollection([]);
    for (let year = 2014; year <= 2017; year++) {
      const startDate = ee.Date.fromYMD(year, startMonth, startDay);
      const endDate = ee.Date.fromYMD(year, endMonth, endDay);
      const collectionYear = fireCollection
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .select('FireMask');
      allFireImages = allFireImages.merge(collectionYear);
    }

    const collectionSize = allFireImages.size().getInfo();
    console.log(`${label} Images: ${collectionSize}`);

    if (collectionSize === 0) {
      return { count: 0, reason: 'C1' }; // No images found for this period
    }

    // Process each image to get high-confidence fires (FireMask == 7)
    // The FireMask band has values: 0=not fire, 7=high confidence, 8=medium, 9=low.
    const fireDetected = allFireImages.map(image =>
      image.eq(7).selfMask().rename('fire_count') // Mask out non-high confidence fires, result is 1 where fire, 0 otherwise
    );

    const fireDetectedSize = fireDetected.size().getInfo();
    if (fireDetectedSize === 0) {
      return { count: 0, reason: 'C1' }; // Even after filtering year by year, if merged collection is empty, report C1
    }

    // Sum all fire pixels over the entire period
    const totalFireCount = fireDetected.sum()
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 1000, // MODIS resolution is ~1km, so 1000m scale is appropriate
        maxPixels: 1e9
      })
      .get('fire_count');

    let result = null;
    try {
      result = await new Promise((resolve, reject) => {
        totalFireCount.evaluate((val, err) => {
          if (err) reject(err);
          else resolve(val);
        });
      });
    } catch (e) {
      console.log(`Calculation error for ${label}: ${e.message}`);
      return { count: null, reason: 'C3' };
    }

    if (result === null || typeof result !== 'number' || isNaN(result)) {
      console.log(`Calculation result for ${label} is invalid: ${result}`);
      return { count: null, reason: 'C3' };
    }

    // Check if valid pixels exist after masking
    const pixelCountCheck = fireDetected.mosaic().reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    }).get('fire_count');

    let validPixels = null;
    try {
      validPixels = await new Promise((resolve, reject) => {
        pixelCountCheck.evaluate((val, err) => {
          if (err) reject(err);
          else resolve(val);
        });
      });
    } catch (e) {
      console.log(`Pixel count check error for ${label}: ${e.message}`);
      return { count: null, reason: 'C3' }; // Error during pixel count check
    }

    if (validPixels === 0) {
        return { count: result, reason: 'C2' }; // Images exist but no valid pixels after processing/masking
    }

    return { count: result, reason: null };
  };

  // 2. Data Acquisition & Check
  const febResult = await getFirePixels(2, 2, 1, 28, 'February (2014-2017)'); // Use 28 to be consistent across years
  const octResult = await getFirePixels(10, 10, 1, 31, 'October (2014-2017)');

  if (febResult.reason === 'C1' && octResult.reason === 'C1') {
    console.log("C1");
    return;
  } else if (febResult.reason === 'C1' || octResult.reason === 'C1') {
    console.log("C1"); // If even one period is empty, it's hard to compare
    return;
  }

  if (febResult.reason === 'C3' || octResult.reason === 'C3') {
    console.log("C3");
    return;
  }

  // 3. Check for C2: No Valid Pixels (after masking)
  // If count is 0 due to valid no-fire detections, it's not C2. C2 implies imagery exists but processing removed all pixels.
  // In our case, the 'selfMask' and 'sum' reducer will naturally result in 0 if no fires are detected.
  // The 'validPixels' check above helps determine if any pixels contributed to the sum.
  // If result.count is 0 but validPixels > 0, it means no fires were detected.
  // If validPixels is 0, it means the area was entirely masked for some other reason (e.g., no data, but unlikely with MODIS)
  // For fire products, a count of 0 usually means no fires.

  if (febResult.reason === 'C2' || octResult.reason === 'C2') {
    console.log("C2");
    return;
  }

  const febFireCount = febResult.count;
  const octFireCount = octResult.count;

  // 4. Validation & Final Answer
  console.log(`Total February Fire Pixels (2014-2017): ${febFireCount}`);
  console.log(`Total October Fire Pixels (2014-2017): ${octFireCount}`);

  if (febFireCount === null || octFireCount === null || typeof febFireCount !== 'number' || typeof octFireCount !== 'number') {
    console.log("C3");
  } else if (febFireCount > octFireCount) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
